using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;
using RepairCenter.Api.Data;
using RepairCenter.Api.Models;
using System.Data;
namespace RepairCenter.Api.Controllers;
[ApiController]
[Route("api/equipment")]
public sealed class EquipmentController : ControllerBase
{
    private readonly SqlConnectionFactory _factory; public EquipmentController(SqlConnectionFactory factory)=>_factory=factory;
    private const string Q="SELECT e.EquipmentID,e.ClientID,c.FullName,e.EquipmentModelID,t.TypeName,b.BrandName,m.ModelName,e.SerialNumber,e.Notes FROM dbo.Course_project_0502_Equipment e JOIN dbo.Course_project_0502_Clients c ON c.ClientID=e.ClientID JOIN dbo.Course_project_0502_EquipmentModels m ON m.EquipmentModelID=e.EquipmentModelID JOIN dbo.Course_project_0502_EquipmentBrands b ON b.EquipmentBrandID=m.EquipmentBrandID JOIN dbo.Course_project_0502_EquipmentTypes t ON t.EquipmentTypeID=m.EquipmentTypeID";
    private static object Map(SqlDataReader r)=>new{EquipmentID=r.GetInt32(0),ClientID=r.GetInt32(1),ClientName=r.GetString(2),EquipmentModelID=r.GetInt32(3),EquipmentType=r.GetString(4),Brand=r.GetString(5),Model=r.GetString(6),SerialNumber=r.GetString(7),Notes=r.IsDBNull(8)?null:r.GetString(8)};
    [HttpGet] public async Task<IActionResult> GetAll([FromQuery]string? search){var rows=new List<object>();await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText=Q+" WHERE @s IS NULL OR e.SerialNumber LIKE @p OR c.FullName LIKE @p OR m.ModelName LIKE @p OR b.BrandName LIKE @p ORDER BY c.FullName";cmd.Parameters.Add("@s",SqlDbType.NVarChar,150).Value=string.IsNullOrWhiteSpace(search)?DBNull.Value:search.Trim();cmd.Parameters.Add("@p",SqlDbType.NVarChar,400).Value=string.IsNullOrWhiteSpace(search)?DBNull.Value:"%"+search.Trim()+"%";await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add(Map(r));return Ok(rows);}
    [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText=Q+" WHERE e.EquipmentID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;await using var r=await cmd.ExecuteReaderAsync();return await r.ReadAsync()?Ok(Map(r)):NotFound();}
    [HttpPost] public async Task<IActionResult> Create(EquipmentRequest request){await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO dbo.Course_project_0502_Equipment(ClientID,EquipmentModelID,SerialNumber,Notes) OUTPUT INSERTED.EquipmentID VALUES(@c,@m,@s,@n)";cmd.Parameters.Add("@c",SqlDbType.Int).Value=request.ClientID;cmd.Parameters.Add("@m",SqlDbType.Int).Value=request.EquipmentModelID;cmd.Parameters.Add("@s",SqlDbType.NVarChar,100).Value=request.SerialNumber.Trim();cmd.Parameters.Add("@n",SqlDbType.NVarChar,300).Value=(object?)request.Notes??DBNull.Value;var id=Convert.ToInt32(await cmd.ExecuteScalarAsync());return CreatedAtAction(nameof(Get),new{id},new{EquipmentID=id});}
    [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,EquipmentRequest request){await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="UPDATE dbo.Course_project_0502_Equipment SET ClientID=@c,EquipmentModelID=@m,SerialNumber=@s,Notes=@n WHERE EquipmentID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;cmd.Parameters.Add("@c",SqlDbType.Int).Value=request.ClientID;cmd.Parameters.Add("@m",SqlDbType.Int).Value=request.EquipmentModelID;cmd.Parameters.Add("@s",SqlDbType.NVarChar,100).Value=request.SerialNumber.Trim();cmd.Parameters.Add("@n",SqlDbType.NVarChar,300).Value=(object?)request.Notes??DBNull.Value;return await cmd.ExecuteNonQueryAsync()==0?NotFound():NoContent();}
    [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){try{await using var c=_factory.Create();await c.OpenAsync();await using var cmd=c.CreateCommand();cmd.CommandText="DELETE FROM dbo.Course_project_0502_Equipment WHERE EquipmentID=@id";cmd.Parameters.Add("@id",SqlDbType.Int).Value=id;return await cmd.ExecuteNonQueryAsync()==0?NotFound():NoContent();}catch(SqlException ex)when(ex.Number==547){return Conflict(new{message="Устройство связано с заказом, удаление запрещено."});}}
}
